target.css:
:root {
  --ink: #24322b;
  --muted: #718078;
  --paper: #fffdf6;
  --line: #d9dfcc;
  --honey: #e7ac36;
  --honey-pale: #fff1c8;
  --leaf: #47765d;
  --leaf-pale: #e5f0e6;
  --alert: #b96042;
}

* {
  box-sizing: border-box;
}

.hive-card {
  width: 488px;
  padding: 15px 16px 13px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.topbar {
  display: flex;
  align-items: center;
  gap: 10px;
}

.mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 12px;
  background: var(--honey-pale);
  color: var(--honey);
  font-size: 24px;
  font-weight: 700;
}

.title-group {
  flex: 1;
}

.eyebrow,
.note {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: .05em;
  text-transform: uppercase;
}

h1,
h2 {
  margin: 0;
}

h1 {
  font-size: 20px;
  line-height: 1.15;
  letter-spacing: -.02em;
}

.state {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--leaf-pale);
  color: var(--leaf);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 13px 0 12px;
}

.metric {
  display: flex;
  min-height: 56px;
  flex-direction: column;
  justify-content: space-between;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
}

.metric span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.metric strong {
  font-size: 16px;
  line-height: 1;
}

.metric.accent {
  border-color: var(--honey);
  background: var(--honey-pale);
}

.inspection {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 9px 0 8px;
}

.inspection-head,
.footer,
.checklist li {
  display: flex;
  align-items: center;
}

.inspection-head {
  justify-content: space-between;
  margin-bottom: 5px;
}

h2 {
  font-size: 13px;
  letter-spacing: -.01em;
}

.legend {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--muted);
  font-size: 10px;
}

.legend i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--honey);
}

.checklist {
  display: grid;
  gap: 3px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.checklist li {
  gap: 7px;
  min-height: 20px;
  font-size: 12px;
}

.check {
  display: grid;
  width: 17px;
  height: 17px;
  flex: 0 0 17px;
  place-items: center;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 800;
}

.check.done {
  background: var(--leaf-pale);
  color: var(--leaf);
}

.check.watch {
  background: var(--honey-pale);
  color: var(--honey);
}

.check.open {
  border: 1px solid var(--line);
  color: var(--muted);
}

.checklist time {
  margin-left: auto;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .06em;
}

.footer {
  justify-content: space-between;
  padding-top: 11px;
}

button {
  border: 0;
  border-radius: 8px;
  padding: 7px 10px;
  background: var(--ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

